layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgba(255, 255, 255, 0.03); border-left: 4px solid rgb(19, 24, 31); border-radius: 0px 8px 8px 0px; box-shadow: rgba(0, 0, 0, 0.2) 0px 1px 2px 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 16px; padding-bottom: 16px; padding-left: 16px; transition: background-color 0.3s, color 0.3s, border-color 0.3s, box-shadow 0.3s; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { background-color: rgb(30, 41, 59); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 16px; box-shadow: rgba(0, 0, 0, 0.3) 0px 4px 6px -1px, rgba(0, 0, 0, 0.2) 0px 2px 4px -1px; transition: background-color 0.3s, color 0.3s, border-color 0.3s, box-shadow 0.3s }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.3s, color 0.3s, border-color 0.3s, box-shadow 0.3s; padding-bottom: 6px; position: relative }
[data-ryt="hero"] h1 { color: rgb(248, 250, 252); font-family: var(--ryt-font-heading); font-size: 44px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: -1.1px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 250, 252); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(248, 250, 252); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: -1.1px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 250, 252); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: italic; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: -0.6px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.3s, color 0.3s, border-color 0.3s, box-shadow 0.3s; padding-bottom: 6px; position: relative }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: background-color 0.3s, color 0.3s, border-color 0.3s, box-shadow 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(248, 250, 252); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: -0.6px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 250, 252); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a:hover { color: #0b65ff }
[data-ryt="rec-card"] [data-ryt="title"] a::before { content: ""; display: block; position: absolute; width: 100%; height: 2px; color: var(--ryt-accent); background-image: linear-gradient(135deg, var(--ryt-accent) 0%, rgb(11, 101, 255) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: -0.6px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.3s ease-out; -webkit-text-fill-color: var(--ryt-accent); bottom: -2px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #0b65ff }
[data-ryt="credit"] a::before, [data-ryt="review"] a::before, [data-ryt="bio"] a::before { content: ""; display: block; position: absolute; width: 100%; height: 2px; color: var(--ryt-accent); background-image: linear-gradient(135deg, var(--ryt-accent) 0%, rgb(11, 101, 255) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.3s ease-out; -webkit-text-fill-color: var(--ryt-accent); bottom: -2px; left: 0px }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #0b65ff }
